     render(<SuccessPage params={Promise.resolve({ id: 'request-123' })} />);

     await waitFor(() => {
       expect(screen.getByRole('button', { name: /copy link/i })).toBeInTheDocument();
     });

     await user.click(screen.getByRole('button', { name: /copy link/i }));

