               )}
             </p>
             {hasUnresolvedResults && (
               <ul className="text-sm space-y-1">
                 {unresolvedResults.map((result) => (
                   <li key={result.assetId}>
                     {result.assetName}: {result.errorMessage || content.pending}
                   </li>
