   onSelectionChange: (selectedAssets: {
     adAccounts: string[];
     pages: string[];
     instagramAccounts: string[];
     selectedBusinessId?: string;
     selectedBusinessName?: string;
     businesses?: Array<{ id: string; name: string }>;
