         method: 'POST',
         headers: {
           'Content-Type': 'application/json',
           Authorization: `Bearer ${token}`,
         },
         body: JSON.stringify(data),
       });

       if (!response.ok) {
         const msg = await extractApiErrorMessage(response, 'Failed to create client');
         throw new Error(msg);
       }

       return response.json();
     },
