           >
             {currentStep.primaryAction.loading
               ? currentStep.primaryAction.loadingLabel || 'Processing...'
               : currentStep.primaryAction.label}
             {!currentStep.primaryAction.loading ? <ChevronRight className="h-4 w-4" /> : null}
-          </button>
