   const [formState, setFormState] = useState<FormState>({
     name: '',
     email: '',
     companyName: '',
     websiteUrl: '',
     promotionPlan: '',
   });
   const [status, setStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');
