             >
               {/* Header */}
               <div className="flex items-center justify-between p-6 border-b border-border">
                 <h2 className="text-lg font-semibold text-ink">Save as Template</h2>
                 <button
                   type="button"
                   onClick={onClose}
-                  className="p-1 hover:bg-muted/30 rounded-lg transition-colors"
